import os
import torch

# ====================================================
# General Settings
# ====================================================
SEED = 42
DEBUG = False  # Set to True for quick testing with fewer batches
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

# ====================================================
# Directory Paths
# ====================================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_4"

# Metadata files generated by the EDA/Metadata script
TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

# Output directories
CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
PREDICTION_DIR = os.path.join(WORKING_DIR, "predictions")
LOG_DIR = os.path.join(WORKING_DIR, "logs")

# Ensure output directories exist
os.makedirs(CHECKPOINT_DIR, exist_ok=True)
os.makedirs(PREDICTION_DIR, exist_ok=True)
os.makedirs(LOG_DIR, exist_ok=True)

# ====================================================
# Data Configuration
# ====================================================
# Input image characteristics
# Max dimensions in dataset are approx 310x360.
# We use dimensions divisible by 32 for U-Net architectures.
IMAGE_SIZE = (320, 384)  # (Height, Width)
IN_CHANNELS = 3  # 2.5D: Slice t-1, t, t+1
NUM_CLASSES = 3  # Large Bowel, Small Bowel, Stomach
CLASS_LABELS = ["large_bowel", "small_bowel", "stomach"]

# Data Loading
NUM_WORKERS = 4  # Optimized for 12 vCPUs
PREFETCH_FACTOR = 2

# ====================================================
# Model Configuration
# ====================================================
ARCH = "UnetPlusPlus"
BACKBONE = "efficientnet-b4"
ENCODER_WEIGHTS = "imagenet"
DEEP_SUPERVISION = True  # Enable deep supervision for U-Net++

# ====================================================
# Training Configuration
# ====================================================
EPOCHS = 15
BATCH_SIZE = 32  # Maximize for A100 40GB
LEARNING_RATE = 2e-4
WEIGHT_DECAY = 1e-5
MAX_GRAD_NORM = 1000
MIXED_PRECISION = True  # Use AMP

# Learning Rate Scheduler
SCHEDULER = "CosineAnnealingLR"
MIN_LR = 1e-6
T_MAX = EPOCHS

# ====================================================
# Loss Configuration
# ====================================================
# Combined Loss: BCE + Tversky
# Tversky weights to penalize False Positives (alpha < beta)
TVERSKY_ALPHA = 0.3
TVERSKY_BETA = 0.7
TVERSKY_SMOOTH = 1.0
# Weights for the combined loss
BCE_WEIGHT = 0.5
TVERSKY_WEIGHT = 0.5

# ====================================================
# Inference / Post-processing Configuration
# ====================================================
# Thresholds for converting probabilities to binary masks
THR_LARGE_BOWEL = 0.5
THR_SMALL_BOWEL = 0.5
THR_STOMACH = 0.5

# 3D CCA settings
MIN_COMPONENT_SIZE = 50  # Minimum volume in pixels to keep a component


# ====================================================
# Reproducibility
# ====================================================
def seed_everything(seed=42):
    import random
    import numpy as np

    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


# Set seed immediately upon import
seed_everything(SEED)
